{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE eggozdb.maplemonk.my_sql_COCO_DATA AS WITH base_orders AS ( SELECT oc1.customer_id, oc1.retailer_id, rc.phone_no, rr.retailer_type, DATE_TRUNC(\'MONTH\', TIMESTAMPADD(MINUTE, 330, oc1.created_at)) AS order_month FROM eggozdb.maplemonk.my_sql_order_cmsorder oc1 LEFT JOIN eggozdb.maplemonk.my_sql_retailer_cmscustomer rc ON oc1.customer_id = rc.id LEFT JOIN eggozdb.maplemonk.my_sql_retailer_retailer rr ON oc1.retailer_id = rr.id WHERE rr.retailer_type = \'Coco\' ), customer_cohort AS ( SELECT customer_id, retailer_id, phone_no, MIN(order_month) AS cohort_month FROM base_orders GROUP BY customer_id, retailer_id, phone_no ), cohort_size AS ( SELECT cohort_month, retailer_id, COUNT(DISTINCT customer_id) AS cohort_customers FROM customer_cohort GROUP BY cohort_month, retailer_id ), retention_calc AS ( SELECT cc.cohort_month, cc.retailer_id, DATEDIFF(MONTH, cc.cohort_month, bo.order_month) AS month_number, TO_CHAR(bo.order_month, \'Mon YYYY\') AS month_name, COUNT(DISTINCT cc.customer_id) AS retained_customers FROM customer_cohort cc LEFT JOIN base_orders bo ON cc.customer_id = bo.customer_id AND cc.retailer_id = bo.retailer_id GROUP BY cc.cohort_month, cc.retailer_id, month_number, month_name ), final_retention AS ( SELECT r.cohort_month, r.retailer_id, r.month_number, r.month_name, r.retained_customers, cs.cohort_customers, ROUND(r.retained_customers * 100.0 / NULLIF(cs.cohort_customers, 0), 2) AS retention_rate FROM retention_calc r LEFT JOIN cohort_size cs ON r.cohort_month = cs.cohort_month AND r.retailer_id = cs.retailer_id ), customer_month_eggtype AS ( SELECT o.customer_id, o.retailer_id, DATE_TRUNC(\'MONTH\', TIMESTAMPADD(MINUTE, 330, o.created_at)) AS order_month, CASE WHEN UPPER(CONCAT(p.sku_count, p.short_name)) LIKE \'%B%\' AND UPPER(CONCAT(p.sku_count, p.short_name)) NOT LIKE \'%W%\' THEN \'Brown\' WHEN UPPER(CONCAT(p.sku_count, p.short_name)) LIKE \'%W%\' AND UPPER(CONCAT(p.sku_count, p.short_name)) NOT LIKE \'%B%\' THEN \'White\' ELSE \'Mixed\' END AS egg_type_grain, COUNT(DISTINCT o.customer_id) AS unique_customers_in_month FROM eggozdb.maplemonk.my_sql_order_cmsorder o LEFT JOIN eggozdb.maplemonk.my_sql_order_cmsorderline ol ON ol.cms_order_id = o.id LEFT JOIN eggozdb.maplemonk.my_sql_product_product p ON p.id = ol.product_id LEFT JOIN eggozdb.maplemonk.my_sql_retailer_retailer rr ON o.retailer_id = rr.id WHERE rr.retailer_type = \'Coco\' GROUP BY o.customer_id, o.retailer_id, order_month, egg_type_grain ), customer_egg_type AS ( SELECT o.customer_id, o.retailer_id, DATE_TRUNC(\'MONTH\', TIMESTAMPADD(MINUTE, 330, o.created_at)) AS order_month, CASE WHEN COUNT(DISTINCT CASE WHEN UPPER(CONCAT(p.sku_count, p.short_name)) LIKE \'%B%\' AND UPPER(CONCAT(p.sku_count, p.short_name)) NOT LIKE \'%W%\' THEN \'Brown\' WHEN UPPER(CONCAT(p.sku_count, p.short_name)) LIKE \'%W%\' AND UPPER(CONCAT(p.sku_count, p.short_name)) NOT LIKE \'%B%\' THEN \'White\' END ) > 1 THEN \'Mixed\' WHEN MAX( CASE WHEN UPPER(CONCAT(p.sku_count, p.short_name)) LIKE \'%B%\' AND UPPER(CONCAT(p.sku_count, p.short_name)) NOT LIKE \'%W%\' THEN \'Brown\' END ) = \'Brown\' THEN \'Brown\' WHEN MAX( CASE WHEN UPPER(CONCAT(p.sku_count, p.short_name)) LIKE \'%W%\' AND UPPER(CONCAT(p.sku_count, p.short_name)) NOT LIKE \'%B%\' THEN \'White\' END ) = \'White\' THEN \'White\' ELSE \'Mixed\' END AS customer_egg_type FROM eggozdb.maplemonk.my_sql_order_cmsorder o LEFT JOIN eggozdb.maplemonk.my_sql_order_cmsorderline ol ON ol.cms_order_id = o.id LEFT JOIN eggozdb.maplemonk.my_sql_product_product p ON p.id = ol.product_id LEFT JOIN eggozdb.maplemonk.my_sql_retailer_retailer rr ON o.retailer_id = rr.id WHERE rr.retailer_type = \'Coco\' GROUP BY o.customer_id, o.retailer_id, order_month ), customer_active_months AS ( SELECT DISTINCT oc1.customer_id, oc1.retailer_id, DATE_TRUNC(\'MONTH\', TIMESTAMPADD(MINUTE, 330, oc1.created_at)) AS active_month FROM eggozdb.maplemonk.my_sql_order_cmsorder oc1 LEFT JOIN eggozdb.maplemonk.my_sql_retailer_retailer rr ON oc1.retailer_id = rr.id WHERE rr.retailer_type = \'Coco\' ), customer_next_order AS ( SELECT cam.customer_id, cam.retailer_id, cam.active_month, MIN(cam2.active_month) AS next_order_month FROM customer_active_months cam LEFT JOIN customer_active_months cam2 ON cam.customer_id = cam2.customer_id AND cam.retailer_id = cam2.retailer_id AND cam2.active_month > cam.active_month GROUP BY cam.customer_id, cam.retailer_id, cam.active_month ), monthly_churn_stats AS ( SELECT cno.retailer_id, cno.active_month, COUNT(DISTINCT cno.customer_id) AS monthly_active_customers, COUNT(DISTINCT CASE WHEN DATEDIFF(DAY, LAST_DAY(cno.active_month), COALESCE(cno.next_order_month, \'9999-12-31\')) BETWEEN 31 AND 89 THEN cno.customer_id END ) AS monthly_churn_30_90_customers, COUNT(DISTINCT CASE WHEN DATEDIFF(DAY, LAST_DAY(cno.active_month), cno.next_order_month) >= 90 OR ( cno.next_order_month IS NULL AND DATEDIFF(DAY, LAST_DAY(cno.active_month), CURRENT_DATE()) > 90 ) THEN cno.customer_id END ) AS monthly_churn_90_customers FROM customer_next_order cno GROUP BY cno.retailer_id, cno.active_month ) SELECT oc1.customer_id, oc1.retailer_id, rr.billing_name_of_shop, oc.mrp, oc.quantity * oc.mrp AS MRP_VALUE, oc.quantity, oc.single_sku_rate, oc1.total_amount, oc.single_sku_rate * oc.quantity AS sku_value, oc1.discount_amount, oc1.discount_id, oc1.referral_source, rc.name, rc.phone_no, oc1.id, CONCAT(\'ord-\', oc1.id) AS \"Invoice No\", CONCAT(pp.sku_count, pp.short_name) AS sku_name, oc1.created_at, (pp.sku_count * oc.quantity) AS egg_count, CAST(TIMESTAMPADD(MINUTE, 330, oc1.created_at) AS DATE) AS Date, TIMESTAMPADD(MINUTE, 330, oc1.created_at) AS Time_stamp, bn.rate, bn.city_name, fr.cohort_month, fr.month_number, fr.month_name, fr.retained_customers, fr.cohort_customers, fr.retention_rate, rr.retailer_type, CASE WHEN (oc.single_sku_rate * oc.quantity) = 0 THEN \'Promo\' ELSE \'Sales\' END AS order_type, CASE WHEN DATE_TRUNC(\'MONTH\', TIMESTAMPADD(MINUTE, 330, oc1.created_at)) <= DATE_TRUNC(\'MONTH\', CURRENT_DATE()) THEN \'Yes\' ELSE \'No\' END AS active_customer_last_30_days, CASE WHEN DATE_TRUNC(\'MONTH\', TIMESTAMPADD(MINUTE, 330, oc1.created_at)) = cc.cohort_month THEN \'New\' ELSE \'Repeating\' END AS customer_type, CONCAT(oc1.customer_id, \'_\', DATE_TRUNC(\'MONTH\', TIMESTAMPADD(MINUTE, 330, oc1.created_at))) AS unique_customer_month_key, oc1.customer_id AS total_unique_customer, CASE WHEN DATEDIFF(DAY, LAST_DAY(cno.active_month), COALESCE(cno.next_order_month, \'9999-12-31\')) BETWEEN 31 AND 89 THEN \'Yes\' ELSE \'No\' END AS churn_gt_30_lt_90_days, CASE WHEN DATEDIFF(DAY, LAST_DAY(cno.active_month), cno.next_order_month) >= 90 OR ( cno.next_order_month IS NULL AND DATEDIFF(DAY, LAST_DAY(cno.active_month), CURRENT_DATE()) > 90 ) THEN \'Yes\' ELSE \'No\' END AS churn_gt_90_days, mcs.monthly_active_customers, (mcs.monthly_churn_30_90_customers + mcs.monthly_churn_90_customers) AS monthly_churn_customers, ROUND( (mcs.monthly_churn_30_90_customers + mcs.monthly_churn_90_customers) * 100.0 / NULLIF(mcs.monthly_active_customers, 0), 2 ) AS monthly_churn_percentage, CASE WHEN UPPER(CONCAT(pp.sku_count, pp.short_name)) LIKE \'%B%\' AND UPPER(CONCAT(pp.sku_count, pp.short_name)) NOT LIKE \'%W%\' THEN \'Brown\' WHEN UPPER(CONCAT(pp.sku_count, pp.short_name)) LIKE \'%W%\' AND UPPER(CONCAT(pp.sku_count, pp.short_name)) NOT LIKE \'%B%\' THEN \'White\' ELSE \'Mixed\' END AS egg_type, cet.customer_egg_type FROM eggozdb.maplemonk.my_sql_order_cmsorderline oc LEFT JOIN eggozdb.maplemonk.my_sql_order_cmsorder oc1 ON oc.cms_order_id = oc1.id LEFT JOIN eggozdb.maplemonk.my_sql_product_product pp ON pp.id = oc.product_id LEFT JOIN eggozdb.maplemonk.my_sql_retailer_cmscustomer rc ON oc1.customer_id = rc.id LEFT JOIN eggozdb.maplemonk.my_sql_retailer_retailer rr ON oc1.retailer_id = rr.id LEFT JOIN customer_cohort cc ON oc1.customer_id = cc.customer_id AND oc1.retailer_id = cc.retailer_id LEFT JOIN final_retention fr ON cc.cohort_month = fr.cohort_month AND cc.retailer_id = fr.retailer_id AND DATEDIFF(MONTH, cc.cohort_month, DATE_TRUNC(\'MONTH\', TIMESTAMPADD(MINUTE, 330, oc1.created_at))) = fr.month_number LEFT JOIN eggozdb.maplemonk.my_sql_base_neccrates bn ON CAST(TIMESTAMPADD(MINUTE, 330, oc1.created_at) AS DATE) = bn.date AND bn.city_name = \'Barwala\' LEFT JOIN customer_next_order cno ON oc1.customer_id = cno.customer_id AND oc1.retailer_id = cno.retailer_id AND DATE_TRUNC(\'MONTH\', TIMESTAMPADD(MINUTE, 330, oc1.created_at)) = cno.active_month LEFT JOIN monthly_churn_stats mcs ON oc1.retailer_id = mcs.retailer_id AND DATE_TRUNC(\'MONTH\', TIMESTAMPADD(MINUTE, 330, oc1.created_at)) = mcs.active_month LEFT JOIN customer_egg_type cet ON oc1.customer_id = cet.customer_id AND oc1.retailer_id = cet.retailer_id AND DATE_TRUNC(\'MONTH\', TIMESTAMPADD(MINUTE, 330, oc1.created_at)) = cet.order_month WHERE rr.retailer_type = \'Coco\';",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from EGGOZDB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            